    [3, 4],
    [0, 1],
    [2, 0],
    [4, 2],
  ];

  final List<int> graph = List<int>.filled(n, 0);
  final List<int> outdegrees = List<int>.filled(n, 0);

  for (final edge in edges) {
    final u = edge[0];
    final v = edge[1];
    graph[u] |= 1 << v;
    outdegrees[v] += 1;
  }

  final List<int> topoSort = <int>[];
  final List<int> stack = <int>[];

  for (int i = 0; i < n; i++) {
    if (outdegrees[i] == 0) {
      stack.add(i);
    }
  }

  while (stack.isNotEmpty) {
    final u = stack.removeLast();
    topoSort.add(u);

    for (final v = graph[u] & (1 << (u + 1)); v != 0; v >>= 1) {
      if (v & 1 == 1) {
        outdegrees[v - 1]--;
      }
      v >>= 1;
    }
  }

  if (topoSort.length != n) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {
    print('Topological Sort: ${topoSort.join(' -> ')}');
  }
}

