    }
  }

  List<String> ids = regions.keys.toList();
  ids.sort();
  for (String id in ids) {
    int total = 0;
    for (int x in regions[id]!) {
      total += x;
    }
    if (total == 0) {
      results.add('${id}*');
    } else {
      results.add('${id}:${total}');
    }
  }
  return results;
}

