void fn0() {

  List<String> testCases = [
    'EXAMPLE',
    'HERE IS A SIMPLE EXAMPLE',
    'Pattern not found.',
    'Pattern found at positions: 0, 2, 4, 6',
  ];

  for (var test in testCases) {

    List<String> tokens = test.split(' ');

    int n = tokens.length;

    List<String> dp = List.filled(n + 1, '');

    for (int i = 0; i <= n; i++) {
      String prefix = '';
      for (int j = i; j >= 0; j--) {
        prefix += tokens[j];
        if (j == 0 || j == i) {
          dp[i] = prefix;
          break;
        }
      }
    }

    String pattern = '';
    for (int i = 0; i <= n; i++) {
      if (dp[i] == pattern) {
        print('Pattern found at positions: ${i - n + 1}');
        break;
      }
    }
  }
}

