    'Pattern not found.'
  ];

  for (String test in testCases) {

    List<String> words = test.isEmpty ? [''] : test.split(' ');

    List<int> computeLPSArray(String pattern) {
      int m = pattern.length;
      List<int> lps = List.filled(m, 0);
      int len = 0;
      int i = 1;

      while (i < m) {
        if (pattern[i] == pattern[len]) {
          len++;
          lps[i] = len;
          i++;
        } else {
          if (len != 0) {
            len = lps[len - 1];
          } else {
            lps[i] = 0;
            i++;
          }
        }
      }
      return lps;
    }

    List<int> kmpSearch(String text, String pattern) {
      List<int> matches = [];
      int n = text.length;
      int m = pattern.length;

      if (m == 0 || n == 0) {
        return matches;
      }

      List<int> lps = computeLPSArray(pattern);

      int i = 0;
      int j = 0;

      while (i < n) {
        if (pattern[j] == text[i]) {
          i++;
          j++;
        }

        if (j == m) {
          matches.add(i - j);
          j = lps[j - 1];
        } else if (i < n && pattern[j] != text[i]) {
          if (j != 0) {
            j = lps[j - 1];
          } else {
            i++;
          }
        }
      }

      return matches;
    }

    List<int> matches = kmpSearch(test, words[0]);
    print('Pattern found at positions: ${matches.join(', ')}');
