  print(result);
}

List<String> generateCombinations(List<String> items, int k) {
  int n = items.length;
  List<String> combinations = [];

  void backtrack(List<String> current, int start) {
    if (current.length == k) {
      combinations.add(current.join(' '));
      return;
    }

    for (int i = start; i < n; i++) {
      current.add(items[i]);
      backtrack(current, i + 1);
      current.removeLast();
    }
  }

  backtrack([], 0);
  return combinations;
}

