List<int> fn0(List<String> shelfCodes) {
  Set<String> occupied = {};
  List<List<String>> groups = [];
  List<int> totals = [];
  for (String code in shelfCodes) {
    if (code.isEmpty) continue;
    int colon = code.indexOf(':');
    if (colon == -1) {
      occupied.add(code);
    } else {
      String section = code.substring(0, colon);
      String zone = code.substring(colon + 1);
      if (occupied.contains(section)) continue;
      occupied.add(section);
      List<String> items = [];
      for (int i = colon + 2; i < code.length; i++) {
        String char = code[i];
        if (char == ',') {
          if (items.isNotEmpty) {
            groups.add(items);
            items = [];
          }
          continue;
        }
        int count = int.parse(char);
        if (count <= 0) {
          continue;
        }
        for (int j = 0; j < count; j++) {
          items.add(char);
        }
      }
      if (items.isNotEmpty) {
        groups.add(items);
      }
      if (zone.length > 0) {
        occupied.add('$section/$zone');
      }
      int score = 0;
      if (zone == '*') {
        score += items.length * 2;
      } else if (items.isEmpty) {
        score += 1;
      } else {
        int repeated = 0;
        Set<String> seen = {};
        for (String item in items) {
          if (seen.contains(item)) {
            repeated++;
          } else {
            seen.add(item);
          }
        }
        if (repeated >= 2) {
          score -= 1;
        } else {
          score += items.length + repeated;
        }
      }
      totals.add(score);
    }
  }
  for (List<String> group in groups) {
    int score = 0;
    int doubled = 0;
    bool repeats = false;
    for (String item in group) {
      if (item.isEmpty) continue;
      if (item.length > 1 && item[0] == item[item.length - 1]) {
        score += 2;
      } else if (item.length >= 2 && item[0] == item[1]) {
        score += 1;
      }
      bool rare = !occupied.contains(item);
      if (rare) {
        score += 1;
      } else if (doubled >= 2) {
        score -= 1;
      }
      if (doubled > 0) {
        score += 1;
      }
      for (int i = 0; i < item.length; i++) {
        doubled += item.length - i;
        if (doubled > 0) {
          score += 1;
        } else if (i > 0 && item[i] == item[i - 1]) {
          repeats = true;
        }
      }
    }
    if (repeats) {
      score -= 1;
    } else if (doubled >= group.length) {
      score += 2;
    }
    totals.add(score);
  }
  totals.sort();
  return totals;
}

