Map<String, int> fn0(List<int> pings, int maxGap) {
  int n = pings.length;
  if (n == 0 || maxGap < 0) {
    return {'mashupDuration': -1, 'pairCount': 0};
  }
  if (n == 1) {
    return {'mashupDuration': 0, 'pairCount': 0};
  }

  int left = 0;
  int right = n - 1;
  while (left < right) {
    int mid = left + ((right - left) >> 1);
    if (pings[mid] - pings[0] <= maxGap) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int bestLeft = left;
  if (bestLeft > 0) {
    int bestDiff = pings[bestLeft] - pings[0];
    int leftBound = bestLeft - 1;
    while (leftBound >= 0) {
      if (pings[leftBound] - pings[0] < bestDiff) {
        bestDiff = pings[leftBound] - pings[0];
        bestLeft = leftBound + 1;
      }
      leftBound--;
    }
  }

  right = bestLeft;
  while (right < n - 1) {
    int mid = (right + (n - 1) >> 1) + 1;
    if (pings[mid] - pings[mid - 1] <= maxGap) {
      right = mid;
    } else {
      left = mid;
    }
  }

  int endLeft = right;
  int bestDiff = pings[endLeft] - pings[0];
  int rightBound = endLeft + 1;
  while (rightBound < n) {
    if (pings[rightBound] - pings[0] < bestDiff) {
      bestDiff = pings[rightBound] - pings[0];
      endLeft = rightBound;
    }
    rightBound++;
  }

  return {
    'mashupDuration': bestDiff,
    'pairCount': endLeft - bestLeft + 1,
  };
}

