class Quaternion {
  double x = 0.0;
  double y = 0.0;
  double z = 0.0;
  double w = 0.0;

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.basis() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.basis2() : this(0.0, 0.0, 1.0, 0.0);

  const Quaternion.basis3() : this(0.0, 1.0, 0.0, 0.0);

  const Quaternion.basis4() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.basis5() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.basis6() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z - z * other.y + w * other.x,
          y * other.w + x * other.z - z * other.y + w * other.y,
          z * other.w + w * other.x - x * other.y - y * other.z,
          w * other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion conjugate() =>
      Quaternion(x, y, -z, w);

  double norm() => (x * x + y * y + z * z + w * w);

  double inverse() {
    double r = 1 / (x * x + y * y + z * z + w * w);
    return Quaternion(
        x * r, y * r, z * r, w * r - (x * x + y * y + z * z + w * w) * r);
  }

  void rotateZ(double angle) {
    double sin = angle.abs() * 0.5;
    double cos = angle.abs() * 0.5;
    double sx = x * cos + z * sin;
    double sy = y * cos;
    double sz = z * cos - x * sin;
    x = sx;
    y = sy;
    z = sz;
  }

  void rotateY(double angle) {
    double sin = angle.abs() * 0.5;
    double cos = angle.abs() * 0.5;
    double sy = y * cos + z * sin;
    double sz = z * cos - x * sin;
    x = sx;
    y = sy;
    z = sz;
  }

  void rotateX(double angle) {
    double sin = angle.abs() * 0.5;
    double cos = angle.abs() * 0.5;
    double sx = x * cos + y * sin;
    double sy = y * cos - x * sin;
    x = sx;
    y = sy;
    z = z;
  }

  void normalize() {
    double norm = x * x + y * y + z * z + w * w;
    if (norm == 0.0) {
      x = 0.0;
      y = 0.0;
      z = 0.0;
      w = 0.0;
      return;
    }
    double inv = 1 / norm;
    x *= inv;
    y *= inv;
    z *= inv;
    w *= inv;
  }
}

