import 'dart:convert';
class Quaternion {
  double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }

  @override
  bool operator ==(Object other) {
    if (other is Quaternion) {
      return x == other.x && y == other.y && z == other.z && w == other.w;
    }
    return false;
  }

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(Quaternion other) {
    double _x = x * other.w - y * other.z - z * other.y + w * other.x;
    double _y = x * other.z + y * other.w + z * other.x - w * other.y;
    double _z = x * y - w * z;
    double _w = x * z + w * y;
    return Quaternion(_x, _y, _z, _w);
  }

  Quaternion operator *=(Quaternion other) {
    x = x * other.w - y * other.z - z * other.y + w * other.x;
    y = x * other.z + y * other.w + z * other.x - w * other.y;
    z = x * y - w * z;
    w = x * z + w * y;
    return this;
  }

  Quaternion operator -() => Quaternion(-x, -y, -z, -w);

  Quaternion inverse() {
    double inverse = 1 / (x * x + y * y + z * z + w * w);
    return Quaternion(
      x * inverse,
      y * inverse,
      z * inverse,
      w * inverse,
    );
  }

  Quaternion normalized() {
    double norm = x * x + y * y + z * z + w * w;
    if (norm == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  double norm() => x * x + y * y + z * z + w * w;
}

