import 'dart:async';
import 'dart:convert';
class Quaternion {
  double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion(this.x, this.y, this.z) : this(x, y, z, 0);

  Quaternion(this.x, this.y) : this(x, y, 0, 0);

  Quaternion() : this(0, 0, 0, 1);

  double norm() => x * x + y * y + z * z + w * w;

  double conjugateX() => x;
  double conjugateY() => y;
  double conjugateZ() => z;
  double conjugateW() => w;

  Quaternion inverse() {
    return Quaternion(x, y, z, 1 / w);
  }

  Quaternion normalized() {
    final double n = norm();
    if (n == 0) return this;
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion operator +(Quaternion q) =>
      Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);

  Quaternion operator -(Quaternion q) =>
      Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);

  Quaternion operator *(Quaternion q) {
    final double x1 = this.x, y1 = this.y, z1 = this.z, w1 = this.w;
    final double x2 = q.x, y2 = q.y, z2 = q.z, w2 = q.w;
    final double realPart = x1 * x2 - y1 * y2 - z1 * z2 - w1 * w2;
    final double imaginaryPart = x1 * y2 + x2 * y1 + z1 * w2 + z2 * w1;
    return Quaternion(realPart, imaginaryPart, z1 * w2 - x2 * z2, w1 * w2);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  static Quaternion fromAxisAngle(List<double> axis, double angle) {
    final double x = axis[0], y = axis[1], z = axis[2];
    final double cosHalf = (1 - cos(angle / 2)) / 2;
    final double sinHalf = (1 - sin(angle / 2)) / 2;
    return Quaternion(2 * sinHalf * x, 2 * sinHalf * y, 2 * sinHalf * z, cosHalf);
  }

  void rotateAroundAxis(double x, double y, double z, double angle) {
    final Quaternion axisQuat = Quaternion(x, y, z);
    final Quaternion rotation = Quaternion.fromAxisAngle(axisQuat, angle);
    final Quaternion rotated = this * rotation;
    this = rotated;
  }
}

