Map<String, int> fn0(List<int> p0, int p1) {
  List<int> dp = List.filled(p0.length, 1);
  int best = 1;
  for (int i = 0; i < p0.length; i++) {
    dp[i] = p0[i] == 0 ? 1 : dp[i - 1] + 1;
    if (dp[i] > best) best = dp[i];
  }
  if (best == 1) return {"empty": 0, "fit": 0};
  Map<String, int> counts = {"empty": 0, "fit": 0};
  int target = p1;
  int start = 0;
  while (start < p0.length) {
    int len = dp[start];
    if (len >= target) {
      int end = start + len - 1;
      int gap = start;
      for (int i = start; i <= end; i++) {
        if (dp[i] > 1) gap++;
      }
      counts["fit"] = counts["fit"]! + 1;
      counts["empty"] = counts["empty"]! + gap;
      start += len;
    } else {
      start++;
    }
  }
  return counts;
}

