  if (moisture.isEmpty || windowSize <= 0 || windowSize > moisture.length) {
    return <String, int>{};
  }

  int[] counts = List.filled(4, 0);
  for (int i = 0; i < windowSize; i++) {
    int level = moisture[i];
    counts[level]++;
  }

  Map<String, int> result = <String, int>{};
  String key = '';
  int maxCount = 0;

  for (int j = 0; j < 4; j++) {
    if (counts[j] > maxCount) {
      maxCount = counts[j];
      key = j.toString();
    }
  }

  result[key] = maxCount;
  for (int k = windowSize; k < moisture.length; k++) {
    int removed = moisture[k - windowSize];
    counts[removed]++;
    int added = moisture[k];
    counts[added]--;
    if (counts[added] == 0) {
      result.remove(key);
    } else {
      result[added] = (result[added] ?? 0) + 1;
    }
    key = added.toString();
  }
  return result;
}

