    'sensitive_data': {'read': false, 'write': false, 'delete': false},
  };

  Map<String, Map<String, String>> roles = {};
  Map<String, String> roleHierarchy = {};

  void grantPermissions(String user, String role, Map<String, bool> permissions) {
    for (var p in permissions) {
      if (permissions[p.key] == true) {
        roles[p.key] ??= <String>{};
        roles[p.key]!.add(p.value);
      }
    }
    roleHierarchy[role] = user;
  }

  void revokePermissions(String user, String role, Map<String, bool> permissions) {
    if (roles.containsKey(role)) {
      roles[role]!.removeWhere((p) => p == permissions[p.key]);
    }
    if (roleHierarchy.containsKey(role) && roleHierarchy[role] == user) {
      roleHierarchy.remove(role);
    }
  }

  void listRoles(String user) {
    print('Role: $user');
    roles[user]!.forEach((p) {
      print('  - $p');
    });
  }

  void displayRoles(String user) {
    if (roles.containsKey(user)) {
      print('Permissions:');
      for (var p in roles[user]!) {
        print('  - $p');
      }
    } else {
      print('  ❌ User "$user" not found');
    }
  }

  void denyAccess(String user, String resource, String action) {
    print('  ❌ Access denied');
    print('  👤 User "$user" attempts to $action "$resource"');
    print('  ❗️ Current role: ${userPermissions[user]![action]}');
    print('  ⚠️ Role: ${userPermissions[user]!["admin"]}');
  }

  void grantAccess(String user, String resource, String action) {
    if (!userPermissions[user]!.containsKey(action)) {
      denyAccess(user, resource, action);
      return;
    }
    print('  ✅ Access granted');
    print('  👤 User "$user" $action "$resource"');
  }

  String getRoleForUser(String user) {
    return (userPermissions[user]!['admin'] == true)
        ? 'admin'
        : (userPermissions[user]!['read'] == true)
            ? 'viewer'
            : (userPermissions[user]!['write'] == true)
                ? 'editor'
                : 'moderator';
  }

  void elevateUser(String user, String newRole) {
    if (!userPermissions.containsKey(user)) {
      denyAccess(user, 'upgrade', 'upgrade');
      return;
    }
    revokePermissions(user, getRoleForUser(user), userPermissions[user]!);
    userPermissions[user] = {
      'read': true, 
      'write': true, 
      'delete': true, 
      'admin': true, 
    };
    grantPermissions(user, newRole, userPermissions[user]!);
  }

  String getCurrentRole(String user) {
    return getRoleForUser(user);
  }

