    print('\n--- User Permissions Overview ---\n');
    print('User: $user');
    print('Permissions:');
    userPermissions[user]!.forEach((p, v) {
      print('  - $p: $v');
    });
  }

  void displayResourcePermissions(String resource) {
    print('\n--- Resource Access Matrix ---\n');
    print('Resource: $resource');
    print('Permissions:');
    resourcePermissions[resource]!.forEach((p, v) {
      print('  - $p: $v');
    });
  }

  void displayRoleHierarchy() {
