  print('Array Endianness Conversion:');
  for (final value in data) {

    String toHex(int value) {
      return value.toRadixString(16).toUpperCase().padLeft(4, '0').padRight(2, '0');
    }

    String fromHex(String hexStr) {
      int value = 0;
      for (int i = 0; i < hexStr.length; i++) {
        value = value * 16 + hexStr.codeUnitAt(i) - 48;
      }
      return value;
    }

    String toBin(int value) {
      String binary = '';
      for (int i = 3; i >= 0; i--) {
        binary += (value >> i) & 1;
      }
      return binary;
    }

    print(
        'Original value: 0x${toHex(value)} → Binary: ${toBin(value)}');

    int swapped = ((value << 1) & 0xFFFF) | (value >> 7);
    print('16-bit swap of 0x${toHex(value)}: 0x${toHex(swapped)} → Binary: ${toBin(swapped)}');

    swapped = ((swapped << 2) & 0xFFFF) | (swapped >> 8);
    print('32-bit swap of 0x${toHex(value)}: 0x${toHex(swapped)} → Binary: ${toBin(swapped)}');

    int reversed = 0;
    if (value != 0) {
      for (int i = 0; i < 8; i++) {
        reversed = (reversed << 1) | (value >> (16 + i));
      }
    }
    print('Reverse order: 0x${toHex(value)} → 0x${toHex(reversed)}');

    print('Swap back: 0x${toHex(value)} → 0x${toHex(swapped)} → 0x${toHex(reversed)}');

    int beValue = value & 0xFFFF;
    int leValue = ((value >> 16) & 0xFFFF) | ((value & 0xFFFF) << 16);
    print('As Big Endian bytes: [${toHex(beValue.toRadixString(16).toUpperCase().padLeft(2, '0'))}]');
    print('As Little Endian bytes: [${toHex(leValue.toRadixString(16).toUpperCase().padLeft(2, '0'))}]');

    List<int> bytesBE = [beValue.toRadixString(16).toUpperCase().padLeft(2, '0').codeUnitAt(0) - 48,
                         beValue.toRadixString(16).toUpperCase().padLeft(2, '0').codeUnitAt(1) - 48];
    List<int> bytesLE = [leValue.toRadixString(16).toUpperCase().padLeft(2, '0').codeUnitAt(0) - 48,
                         leValue.toRadixString(16).toUpperCase().padLeft(2, '0').codeUnitAt(1) - 48];
    print('To bytes: [${bytesBE.join(', ')} → ${bytesLE.join(', ')}]');

    int reconstructedBE = fromHex(bytesBE.join(''));
    int reconstructedLE = fromHex(bytesLE.join(''));
    print('Reconstructed: [${toHex(reconstructedBE)} → ${toHex(reconstructedLE)}]');

    int networkValue = ((value >> 16) & 0xFFFF) | (value & 0xFFFF) & 0xFFFFFFFF;
    print('Network bytes: [${toHex(networkValue.toRadixString(16).toUpperCase().padLeft(4, '0'))}]');
