@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final dataset = <List<String>>[
    ['Milk', 'Bread', 'Butter'],
    ['Milk', 'Bread'],
    ['Bread', 'Butter'],
    ['Milk'],
    ['Butter'],
    ['Milk', 'Bread', 'Butter'],
  ];

  final minSupport = 2; 
  final minConfidence = 0.7;   

  final int k = dataset[0].length; 
  final Map<String, int> itemCount = <String, int>{};
  final Set<String> frequentItems = <String>{};

  for (final item in dataset) {
    for (int i = 0; i < item.length; i++) {
      final String itemSet = item.join(' ');
      if (!frequentItems.contains(itemSet)) {
        frequentItems.add(itemSet);
        itemCount[itemSet] = (itemCount[itemSet] ?? 0) + 1;
      }
    }
  }

  final Map<String, List<String>> itemAssociations = <String, List<String>>{};

  void generateAssociationRules(Map<String, int> itemCount) {
    for (final entry in itemCount.entries) {
      final String item = entry.key;
      final int support = entry.value;
      if (support >= minSupport) {
        final String itemSet = item.join(' ');
        if (itemSet.length > 1) {
          final Map<String, int> itemSetCounts = <String, int>{};
          for (final item2 in dataset) {
            if (item2.length == itemSet.length) {
              final bool isSubset = true;
              for (int j = 0; j < itemSet.length; j++) {
                if (!item2.contains(itemSet[j])) {
                  isSubset = false;
                  break;
                }
              }
              if (isSubset) {
                itemSetCounts[item2.join(' ')] = (itemSetCounts[item2.join(' ')] ?? 0) + 1;
              }
            }
          }
          final Set<String> frequentItemsets = <String>{};
          itemSetCounts.entries.where((e) => e.value >= minSupport).forEach((e) {
            frequentItems.add(e.key);
            frequentItemsets.add(e.key);
          });
          final List<String> items = frequentItemsets.toList();
          if (items.length > 1) {
            final String rule = '${item.join(' -> ')} (support: $support, confidence: ${itemSetCounts[item.join(' ')] / support)';
            itemAssociations[itemSet] = [rule];
          }
        }
      }
    }
  }

  generateAssociationRules(itemCount);

  final Map<String, int> supportCounts = <String, int>{};
  final Map<String, Set<String>> itemSets = <String, Set<String>>{};

  for (final entry in itemAssociations.entries) {
    final String itemSet = entry.key;
    final List<String> rules = entry.value;
    final int support = itemCount[itemSet]!;
    for (final rule in rules) {
      final List<String> items = rule.split(' -> ');
      if (items.length == 2) {
        final String antecedent = items[0];
        final String consequent = items[1];
        final String antecedentSet = antecedent.join(' ');
        final String consequentSet = consequent.join(' ');
        if (antecedentSet.isNotEmpty && consequentSet.isNotEmpty) {
          final Map<String, int> antecedentCounts = <String, int>{};
          for (final item in dataset) {
            if (item.length == antecedentSet.length) {
              final bool isSubset = true;
              for (int j = 0; j < antecedentSet.length; j++) {
                if (!item.contains(antecedentSet[j])) {
                  isSubset = false;
                  break;
                }
              }
              if (isSubset) {
                antecedentCounts[item.join(' ')] = (antecedentCounts[item.join(' ')] ?? 0) + 1;
              }
            }
          }
          final Map<String, int> consequentCounts = <String, int>{};
          for (final item in dataset) {
            if (item.length == consequentSet.length) {
              final bool isSubset = true;
              for (int j = 0; j < consequentSet.length; j++) {
                if (!item.contains(consequentSet[j])) {
                  isSubset = false;
                  break;
                }
              }
              if (isSubset) {
                consequentCounts[item.join(' ')] = (consequentCounts[item.join(' ')] ?? 0) + 1;
              }
            }
          }
          final double antecedentSupport = antecedentCounts[itemSet]! / support;
          final double consequentSupport = consequentCounts[itemSet]! / support;
          final double confidence = antecedentSupport * consequentSupport;
          if (confidence > minConfidence) {
            if (!supportCounts.containsKey(confidence)) {
              supportCounts[confidence] = <String>[];
            }
            supportCounts[confidence]!.add(itemSet);
            itemSets[confidence] = (itemSets[confidence] ?? <String>{})..add(itemSet);
          }
        }
      }
    }
  }

  final Set<String> frequentItemsets = <String>{};
  supportCounts.entries.where((e) => e.value.length >= minSupport).forEach((e) {
    frequentItems.add(e.key);
    frequentItemsets.addAll(e.value);
  });

  final List<String> result = <String>[];
  for (final itemset in frequentItemsets) {
    final int support = itemCount[itemset]!;
    final double confidence = supportCounts[support]!.isEmpty ? 0.0 : supportCounts[support]!.length / frequentItemsets.length;
    result.add(itemset.join(' -> ') + ' (support: $support, confidence: $confidence)');
  }

  result.sort();

  print('Frequent Itemsets:');
  print(frequentItemsets.join(', '));
  print('\nAssociation Rules:');
  for (final rule in result) {
    print(rule);
  }
}

