      for (int item in items) {
        if (itemSupport[item]! >= minSupport) {
          frequentItemsets.add(item);
        }
      }
      return;
    }

    for (int prevK = 1; prevK < k; prevK++) {

      Set<int> prevFrequent = frequentItemsets[prevK]!;
      Map<int, int> prevItemSupport = Map<int, int>.from(itemSupport);

      for (int item in prevFrequent) {
        for (int j = item + 1; j <= k; j++) {
          int newItem = item ^ j;
          if (!prevItemSupport.containsKey(newItem)) {
            prevItemSupport[newItem] = 0;
          }
          prevItemSupport[newItem] = prevItemSupport[newItem]! + 1;
        }
      }

      Set<int> newFrequent = {};
      for (int item in prevFrequent) {
        if (prevItemSupport[item]! >= minSupport) {
          newFrequent.add(item);
        }
      }
      frequentItemsets.add(newFrequent);
    }
  }

  Map<int, int> computeSupport(Set<int> itemset) {
    Map<int, int> support = {};
    int transactionWithItemset = 0;

    for (int t = 0; t < totalTransactions; t++) {
      Set<int> allSubsets = itemset.toSet();
      int tAsSubset = t & allSubsets;
      int tAsSubsetCount = 0;
      while (tAsSubset != 0) {
        tAsSubset &= tAsSubset - 1;
        tAsSubsetCount++;
      }
      transactionWithItemset += tAsSubsetCount;
      for (int item in itemset) {
        if (t & item != 0) {
          support[item] = (support[item] ?? 0) + tAsSubsetCount;
        }
      }
    }
    support[itemset] = transactionWithItemset;
    return support;
  }

  for (int k = 1; k <= 6; k++) {

    Map<int, int> itemSupport = {};
    for (int t = 0; t < totalTransactions; t++) {
      for (int item in items) {
        if ((t & item != 0)) {
          itemSupport[item] = (itemSupport[item] ?? 0) + 1;
        }
      }
    }

