      double confA = (supportCounts[a[0]]! / supportCounts[a[1]]!);
      double confB = (supportCounts[b[0]]! / supportCounts[b[1]]!);
      if (confA != confB) return confB.compareTo(confA);
      return a[0].compareTo(b[0]);
