  for (var rule in itemAssociationRules.entries) {
    int k = rule.key;
    List<List<int>> rules = rule.value;
    print('F${k}:');
    for (var item in rules) {
      print('${item[0]} -> ${item[1]} (support: ${supportCounts[item[0]]}, confidence: ${supportCounts[item[0]] / supportCounts[item[1]]})');
    }
  }
}

