      i++;
      continue;
    }

    if (op != ')') {
      String error = 'Invalid encoded data: Expected ) but found $op';
      throw FormatException(error);
    }

    int bracketStart = i + 1;
    int bracketEnd = len;
    bool inside = false;

    while (i < bracketEnd) {
      String ch = encoded[i];
      if (ch == '(') {
        inside = true;
      } else if (ch == ')') {
        break;
      } else if (inside && (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57)) {
        i++;
      } else {
