        throw FormatException(error);
      }
      i++;
    }

    if (!inside) {
      String error = 'Invalid encoded data: Expected ( but found )';
      throw FormatException(error);
    }

    if (bracketStart == bracketEnd) {
      String error = 'Invalid encoded data: Empty bracket found)';
      throw FormatException(error);
    }

    int bracketLen = bracketEnd - bracketStart;
    if (bracketLen % 2 != 0) {
      String error = 'Invalid encoded data: Odd bracket length found';
      throw FormatException(error);
    }

    for (int j = 0; j < bracketLen; j += 2) {
      int charCode = encoded[bracketStart + j].codeUnitAt(0);
      int count = int.parse(encoded[bracketStart + j + 1]);

      if (count < 1 || count > 256) {
        String error = 'Invalid encoded data: Count outside valid range';
        throw FormatException(error);
      }

      if (charCode >= 97 && charCode <= 122) {
        result.add(charCode - 96);
      }
    }
  }

  return result;
}

