    'totalDeficitDays': 0,
  };

  int n = actualVotes.length;
  List<int> prefix = List.filled(n + 1, 0);
  List<int> suffix = List.filled(n + 1, 0);

  for (int i = n - 1; i >= 0; i--) {
    prefix[i] = actualVotes[i] + (i > 0 ? prefix[i - 1] : 0);
  }

  for (int i = 0; i < n; i++) {
