  int distinctIntervals = 0;
  int totalDeficitDays = 0;

  for (int left = 0; left <= n - targetVotes; left++) {
    int right = left + targetVotes - 1;
    if (right > n - 1) break;

    int prefixLeft = prefix[left];
    int suffixRight = suffix[right];

    int windowSum = prefixLeft < suffixRight ? prefixLeft : suffixRight;
    int windowLen = right - left + 1;

    if (windowLen > longestInterval) {
      longestInterval = windowLen;
    }

    if (windowSum == targetVotes) {
      distinctIntervals++;
    }

    int deficit = targetVotes - windowSum;
    totalDeficitDays += deficit < 0 ? 0 : deficit;
  }

  return {
    'longestInterval': longestInterval,
    'distinctIntervals': distinctIntervals,
    'totalDeficitDays': totalDeficitDays,
  };
}

