}

class Rectangle {
  final double minX;
  final double maxX;
  final double minY;
  final double maxY;

  const Rectangle(
      {required this.minX,
        required this.maxX,
        required this.minY,
        required this.maxY});

  const Rectangle.unit()
      : this(minX: 0, maxX: 1, minY: 0, maxY: 1);

  const Rectangle.fromPoints(Point p1, Point p2)
      : this(minX: p1.x, maxX: p2.x, minY: p1.y, maxY: p2.y);

  Rectangle.fromCenter(double centerX, double centerY, double halfWidth,
          double halfHeight)
      : this(
          minX: centerX - halfWidth,
          maxX: centerX + halfWidth,
          minY: centerY - halfHeight,
          maxY: centerY + halfHeight);

  Rectangle.fromPoints(Point p1, Point p2) {
    final double dx = (p2.x - p1.x).abs();
    final double dy = (p2.y - p1.y).abs();
    return this(
      minX: p1.x,
      maxX: p1.x + 2 * dx,
      minY: p1.y,
      maxY: p1.y + 2 * dy,
    );
  }

  @override
  String toString() => 'Rectangle(center: (${centerX}, $centerY), halfWidth: $halfWidth, halfHeight: $halfHeight)';

  final double centerX = (minX + maxX) / 2;
  final double centerY = (minY + maxY) / 2;
  final double halfWidth = (maxX - minX) / 2;
  final double halfHeight = (maxY - minY) / 2;

  List<Point> getPoints() {
    final List<Point> points = [];
    for (double x = minX; x <= maxX; x++) {
      for (double y = minY; y <= maxY; y++) {
        points.add(Point(x, y));
      }
    }
    return points;
  }

  bool contains(Point p) => p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY;

  bool contains(Rectangle other) =>
      other.minX >= minX && other.maxX <= maxX &&
      other.minY >= minY && other.maxY <= maxY;

  bool intersects(Rectangle other) {
    final double xOverlapStart = minX > other.minX ? minX : other.minX;
    final double xOverlapEnd = maxX < other.maxX ? maxX : other.maxX;
    final double yOverlapStart = minY > other.minY ? minY : other.minY;
    final double yOverlapEnd = maxY < other.maxY ? maxY : other.maxY;

    return xOverlapStart < xOverlapEnd && yOverlapStart < yOverlapEnd;
  }

  Rectangle union(Rectangle other) {
    return Rectangle.fromPoints(
      Point(minX, minY),
      Point(maxX, maxY),
    );
  }

  Rectangle intersect(Rectangle other) {
    if (!this.intersects(other)) return Rectangle.unit();
    return Rectangle.fromPoints(
      Point(other.minX, minY),
      Point(other.maxX, maxY),
    );
  }

  Rectangle subtract(Rectangle other) {
    if (!intersects(other)) return this;
    return Rectangle.fromPoints(
      Point(other.maxX, minY),
      Point(maxX, maxY),
    );
  }
}

