void fn0() async {

  Stream<int> _countUp(int max) async* {
    for (int i = 1; i <= max; i++) {
      yield i;
      await Future.delayed(Duration(milliseconds: 100));
    }
  }

  Stream<int> _fib(int n) async* {
    int a = 0, b = 1;
    while (true) {
      yield a;
      final next = a + b;
      a = b;
      b = next;
      await Future.delayed(Duration(milliseconds: 100));
    }
  }

  Stream<int> _primes(int max) async* {
    final primes = <int>{};
    for (int i = 2; i * i <= max; i++) {
      if (max % i == 0) {
        primes.add(i);
      }
    }
    primes.add(max);
    yield* primes;
  }

  Stream<int> _lazy(Stream<int> source) async* {
    yield* source;
    yield* source;
    yield* source;
  }

  Stream<int> _counter() async* {
    for (int i = 1; i <= 3; i++) {
      yield i;
      await Future.delayed(Duration(milliseconds: 200));
    }
  }

  Stream<int> _combined(Stream<int> source) async* {
    yield 1;
    yield 2;
    yield* source;
    yield 3;
  }

  Stream<int> _numbers() async* {
    yield 42;
    yield 100;
    yield* _lazy(_counter());
    yield* _primes(5);
  }

  print('Counting:');
  await for (final value in _countUp(5)) {
    print('Value: $value');
  }
  print('Done.');

