  await for (final value in _primes(10)) {
    print('Value: $value');
  }
  print('Done.');

  print('Lazy Stream:');
  await for (final value in _lazy(_numbers())) {
    print('Value: $value');
  }
  print('Done.');

  print('Combined Stream:');
  await for (final value in _combined(_numbers())) {
    print('Value: $value');
  }
  print('Done.');
}

