/// Dart program demonstrating async* streams.
/// The main function yields numbers with delays,
/// which are printed by a local generator.
/// The main function also includes a local Future that resolves
/// after the generator completes, allowing the main function to finish.
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Future<void> fn0() async {

  Stream<int> asyncNumbers() async* {
    for (int i = 0; i < 5; i++) {
      await Future.delayed(const Duration(milliseconds: 100));
      yield i; 
    }
  }

  Stream<int> combinedAsyncNumbers() async* {
    yield 100; 
    yield* asyncNumbers(); 
    yield 200; 
  }

  Stream<int> reversedAsyncNumbers() async* {
    yield 300; 
    yield* combinedAsyncNumbers().reversed; 
    yield 400; 
  }

  Stream<int> numbers() async* {
    yield 500;
    yield* reversedAsyncNumbers();
    yield 600;
  }

  await for (var value in numbers()) {
    print('Value: $value');
  }

  print('Counting:');
  await for (var value in numbers()) {
    print(value);
  }

  print('Done.');
}

