Future<void> fn0() async {

  Stream<int> numbers(int start, int end) async* {
    for (int i = start; i <= end; i++) {
      yield i;
    }
  }

  Stream<int> everySecond(int start, int end) async* {
    Timer timer = Timer.every(Duration(seconds: 1));
    while (timer.isActive && (start <= end)) {
      yield start++;
      timer.cancel();
    }
  }

  Stream<int> everyMinute(int start, int end) async* {
    Timer timer = Timer.every(Duration(minutes: 1));
    while (timer.isActive && (start <= end)) {
      yield start++;
      timer.cancel();
    }
  }

  Stream<int> combined(int start, int end) async* {
    yield 0; 
    yield* numbers(1, 3); 
    yield* everySecond(4, 7); 
    yield* everyMinute(8, 11); 
    yield* numbers(12, 15); 
    yield 16; 

    yield* numbers(17, 20); 
    yield* everySecond(21, 24); 
    yield* everyMinute(25, 28); 
    yield* numbers(29, 32); 
    yield 33; 
  }

  print('Counting:');
  await for (var value in combined(1, 3)) {
    print('Value: $value');
  }

  print('\nDone.');
