import 'dart:async';
import 'dart:convert';
class TreeNode {
  final List<TreeNode> children;
  final int value;

  const TreeNode(this.value, [this.children = const []]);
}

void bfs(TreeNode root, int depth) {
  List<TreeNode> queue = [root];
  List<int> levels = [];
  List<int> depths = [];
  List<List<int>> positions = [];

  while (queue.isNotEmpty) {
    TreeNode current = queue.removeAt(0);
    levels.add(current.value);
    depths.add(depth);
    positions.add([current.value, depth]);

    for (TreeNode child in current.children) {
      queue.add(child);
    }
  }

  print('Breadth-first traversal: $levels');
  print('Depth: $depths');
  print('Positions: $positions');
}

